<?php
require __DIR__.'/../app/bootstrap.php'; require_admin();
$id=(int)($_GET['id']??0); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST') {
    check_csrf();
    try {
        if(($_POST['action']??'')==='retry_mail') {
            if(($_POST['checked_delivery']??'')!=='1') throw new DomainException('Kontrollera först om meddelandet redan har kommit fram.');
            $m=one('SELECT * FROM mail_outbox WHERE id=? AND order_id=?',[(int)($_POST['mail_id']??0),$id]);
            $current=one('SELECT status FROM orders WHERE id=?',[$id]);
            if(!$m || $m['state']==='sent' || ($m['state']==='sending' && strtotime($m['attempted_at'])>time()-600)) throw new DomainException('Mejlet är redan skickat eller ett utskick pågår.');
            if($m['kind']==='payment' && $current['status']!=='awaiting_payment') throw new DomainException('Betalningsmejl får inte skickas för denna orderstatus.');
            query("UPDATE mail_outbox SET state='pending' WHERE id=? AND (state IN ('pending','failed') OR (state='sending' AND attempted_at < DATE_SUB(NOW(), INTERVAL 10 MINUTE)))",[$m['id']]);
            dispatch_mail((int)$m['id']); event($id,'Ägaren begärde nytt försök för mejl #'.$m['id'].'.');
        } else { change_order($id,$_POST); dispatch_order_mail($id); }
        $_SESSION['flash']='Ändringen är sparad. Kontrollera mejlstatus nedan vid utskick.';
        redirect('/admin/order.php?id='.$id);
    } catch(DomainException $e) { $error=$e->getMessage(); }
}
$o=one('SELECT * FROM orders WHERE id=?',[$id]); if(!$o) throw new DomainException('Förfrågan finns inte.');
page_start($o['reference']); form_error($error); ?>
<p><a href="/admin/orders.php">← Alla förfrågningar</a></p><p><?=badge($o['status'])?> Inkommen <?=e($o['created_at'])?></p>
<div class="form-grid"><section class="panel"><h2>Kund och leverans</h2><p><?=e($o['name'])?><br><a href="mailto:<?=e($o['email'])?>"><?=e($o['email'])?></a><br><?=e($o['phone'])?></p><p><?=e($o['address'])?><br><?=e($o['postcode'])?> <?=e($o['city'])?><br><?=e($o['country'])?></p><p class="preline"><?=e($o['message'])?></p></section><section class="panel"><h2>Produkt vid förfrågan</h2><p><?=e($o['product_name'])?><br><?=e($o['product_number'])?></p><dl><dt>Produktpris</dt><dd><?=money($o['price_cents'])?></dd><dt>Frakt</dt><dd><?=money($o['shipping_cents'])?></dd><dt>Bekräftat totalpris</dt><dd><?=money($o['total_cents'])?></dd><dt>Betalningssätt</dt><dd><?=$o['payment_method']==='swish'?'Swish':'Betalning enligt överenskommelse'?></dd></dl></section></div>
<form method="post" class="panel"><?=csrf()?><input type="hidden" name="version" value="<?=$o['version']?>"><h2>Anteckningar och betalningsunderlag</h2>
<?php if(in_array($o['status'],['new','confirmed'],true)): field('shipping','Fraktkostnad i SEK',$_POST['shipping']??decimal($o['shipping_cents']??0),'text',true,20); else: ?><p>Frakt och totalpris är låsta efter att betalningsinstruktionen skickats.</p><?php endif ?>
<?php textarea('payment_instruction','Betalningsinstruktion till kunden',$_POST['payment_instruction']??$o['payment_instruction'],5000); textarea('notes','Interna anteckningar (visas aldrig för kunden)',$_POST['notes']??$o['notes'],10000); ?><button name="action" value="save">Spara underlag och anteckningar</button></form>
<section class="panel"><h2>Nästa steg</h2><?php if($o['status']==='new'): ?><p>Ange frakt och bekräfta för att reservera just denna kniv för denna kund. Ingen betalningsinstruktion skickas förrän du har förhandsgranskat och valt att skicka den.</p><form method="post"><?=csrf()?><input type="hidden" name="version" value="<?=$o['version']?>"><?php field('shipping','Fraktkostnad i SEK',decimal($o['shipping_cents']??0),'text',true,20); ?><button name="action" value="confirm">Bekräfta och reservera kniven</button></form>
<?php elseif($o['status']==='confirmed'): try { $preview=payment_preview($o); ?><h3>Förhandsgranska betalningsmejlet</h3><p>Till: <?=e($o['email'])?></p><pre class="mail-preview"><?=e($preview)?></pre><form method="post"><?=csrf()?><input type="hidden" name="version" value="<?=$o['version']?>"><input type="hidden" name="preview_hash" value="<?=e(hash('sha256',$preview))?>"><button name="action" value="send_payment">Skicka betalningsinstruktion till kunden</button></form><?php } catch(DomainException $e) { form_error($e->getMessage()); } ?>
<?php elseif($o['status']==='awaiting_payment'): ?><form method="post"><?=csrf()?><input type="hidden" name="version" value="<?=$o['version']?>"><label class="check"><input type="checkbox" name="payment_checked" value="1" required>Jag har kontrollerat att <?=money($o['total_cents'])?> har kommit in med rätt referens.</label><button name="action" value="paid">Markera betald och kniven som såld</button></form>
<?php elseif($o['status']==='paid'): ?><form method="post"><?=csrf()?><input type="hidden" name="version" value="<?=$o['version']?>"><button name="action" value="shipped">Markera ordern som skickad</button></form>
<?php else: ?><p>Ingen ytterligare åtgärd krävs.</p><?php endif ?>
<?php if(!in_array($o['status'],['shipped','cancelled'],true)): ?><details><summary>Avbryt förfrågan och häv reservation</summary><form method="post"><?=csrf()?><input type="hidden" name="version" value="<?=$o['version']?>"><p>Kniven blir tillgänglig igen om den har reserverats för denna förfrågan. Kontakta kunden separat vid behov.</p><?php if($o['status']==='paid'): ?><label class="check"><input type="checkbox" name="refund_checked" value="1" required>Jag har hanterat eventuell återbetalning manuellt.</label><?php endif ?><button class="danger" name="action" value="cancel">Avbryt och häv reservation</button></form></details><?php endif ?></section>
<section class="panel"><h2>Mejlstatus</h2><p>En sparad förfrågan finns kvar även när mejl misslyckas. Vid osäker leverans: kontrollera utkorgen eller med kunden innan du försöker igen.</p><?php foreach(query('SELECT * FROM mail_outbox WHERE order_id=? ORDER BY id DESC',[$id]) as $m): ?><article class="mail-item"><h3><?=e($m['subject'])?></h3><p><?=e($m['recipient'])?> · <?=badge($m['state'])?> · <?=$m['attempts']?> försök</p><?php if($m['error_code']): ?><p class="error"><?=e($m['error_code']==='ORDER_CANCELLED'?'Betalningsutskicket stoppades när ordern avbröts.':'Mejl kunde inte bekräftas levererat. Kontrollera SMTP-inställningarna på servern.')?></p><?php endif ?><details><summary>Visa mejlinnehåll och datum</summary><p>Skapat <?=e($m['created_at'])?> · Senaste försök <?=e($m['attempted_at'])?> · Skickat <?=e($m['sent_at'])?></p><pre class="mail-preview"><?=e($m['body'])?></pre></details><?php if($m['state']!=='sent' && ($m['kind']!=='payment' || $o['status']==='awaiting_payment')): ?><form method="post"><?=csrf()?><input type="hidden" name="mail_id" value="<?=$m['id']?>"><label class="check"><input type="checkbox" name="checked_delivery" value="1" required>Jag har kontrollerat leveransen och vill försöka skicka detta mejl.</label><button name="action" value="retry_mail" class="secondary">Försök skicka igen</button></form><?php endif ?></article><?php endforeach ?></section>
<section class="panel"><h2>Historik</h2><ul class="history"><?php foreach(query('SELECT * FROM order_events WHERE order_id=? ORDER BY id DESC',[$id]) as $ev): ?><li><time><?=e($ev['created_at'])?></time> — <?=e($ev['description'])?></li><?php endforeach ?></ul></section><?php page_end();
